#!/usr/bin/env node
// Writes the @volo-uti/volo-web-utils helper index into ./AGENTS.md so coding agents find existing helpers.
// `--check` exits 1 when the block is missing or stale (run it in the product's check).
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const ID = "volo-web-utils-index";
const TITLE = "Index of @volo-uti/volo-web-utils";
const INTRO =
  "Generated by volo-web-utils-index; do not edit (rerun after upgrading @volo-uti/volo-web-utils). Before writing a helper, find it here and read its doc file. If nothing fits, say what you looked for first. The doc of each entry is node_modules/@volo-uti/volo-web-utils/docs/<section>/<name>.md ([.] is the docs folder itself). Compound parts and types are in each doc.";

const MAX_CHARS = 8000;
const args = process.argv.slice(2);
const USAGE = `Usage: ${ID} [--check]\n  (no flag)  write the index block into ./AGENTS.md\n  --check    exit 1 when the block is missing or stale`;
if (args.includes("--help") || args.includes("-h")) {
  console.log(USAGE);
  process.exit(0);
}
const unknown = args.filter((arg) => arg !== "--check");
if (unknown.length > 0) {
  console.error(`${ID}: unknown argument ${unknown.map((a) => JSON.stringify(a)).join(", ")}`);
  console.error(USAGE);
  process.exit(1);
}
const check = args.includes("--check");
const target = join(process.cwd(), "AGENTS.md");
const lines = readFileSync(
  join(dirname(fileURLToPath(import.meta.url)), "..", "docs", "index.txt"),
  "utf8",
)
  .trimEnd()
  .split("\n");

const block = [
  `<!-- BEGIN:${ID} -->`,
  "",
  `## ${TITLE}`,
  "",
  INTRO,
  "",
  "```text",
  ...lines,
  "```",
  "",
  `<!-- END:${ID} -->`,
].join("\n");

if (block.length > MAX_CHARS) {
  console.error(`${ID}: the block is ${block.length} characters; the limit is ${MAX_CHARS}`);
  process.exit(1);
}

const pattern = new RegExp(`<!-- BEGIN:${ID} -->[\\s\\S]*?<!-- END:${ID} -->`);
const current = existsSync(target) ? readFileSync(target, "utf8") : "";
const next = pattern.test(current)
  ? current.replace(pattern, () => block)
  : `${current.trimEnd()}${current ? "\n\n" : ""}${block}\n`;

if (check) {
  if (!pattern.test(current)) {
    console.error(`${ID}: AGENTS.md has no ${ID} block; run \`pnpm exec ${ID}\``);
    process.exit(1);
  }
  if (next !== current) {
    console.error(`${ID}: the block in AGENTS.md is stale; run \`pnpm exec ${ID}\``);
    process.exit(1);
  }
  console.log(`${ID}: AGENTS.md block is current`);
} else {
  writeFileSync(target, next);
  console.log(
    `${ID}: wrote ${lines.filter((l) => !l.startsWith("[")).length} entries to AGENTS.md`,
  );
}
